import { Controller } from '@nestjs/common';

// 이 기능은 화면만 만든다.
// 고과·상벌 API(POST/PATCH/GET /hr-card-items)는 다른 기능이 만든다.
@Controller('api/v1')
export class FnSfr01501Controller {}

