import { useState } from 'react';
import {
  call,
  useData,
  Badge,
  DateText,
  Filters,
  Band,
  DataTable,
  Pager,
  Drawer,
  Pairs,
  Form,
  Field,
  TextInput,
  DateInput,
  Select,
  LookupSelect,
  RefName,
  ErrorText,
  Tiles,
} from '../kit';
import type { PageProps, Row, Page } from '../kit';

const TYPES: [string, string][] = [
  ['인사고과', '인사고과'],
  ['상벌', '상벌'],
];
const SIZE = 20;

export default function FnSfr01501Page({ role, notify }: PageProps) {
  const [employeeId, setEmployeeId] = useState<number | string>('');
  const [itemType, setItemType] = useState('인사고과');
  const [applied, setApplied] = useState<{ employeeId: number | string; itemType: string }>({ employeeId: '', itemType: '인사고과' });
  const [page, setPage] = useState(0);
  const [detail, setDetail] = useState<Row | null>(null);
  const [creating, setCreating] = useState(false);
  const [editing, setEditing] = useState<Row | null>(null);

  const [newEmployeeId, setNewEmployeeId] = useState<number | string>('');
  const [newType, setNewType] = useState('인사고과');
  const [title, setTitle] = useState('');
  const [content, setContent] = useState('');
  const [startDate, setStartDate] = useState('');
  const [endDate, setEndDate] = useState('');

  const list = useData<Page>(async () => {
    if (applied.employeeId === '') {
      return { items: [], page: 0, size: SIZE, total: 0 };
    }
    return call<Page>('GET', '/hr-card-items', role, undefined, {
      employeeId: applied.employeeId,
      itemType: applied.itemType,
      page,
      size: SIZE,
    });
  }, [applied, page, role]);

  const rows = list.data ? list.data.items : [];
  const total = list.data ? list.data.total : 0;

  function search() {
    setPage(0);
    setApplied({ employeeId, itemType });
  }

  function reset() {
    setEmployeeId('');
    setItemType('인사고과');
    setPage(0);
    setApplied({ employeeId: '', itemType: '인사고과' });
  }

  function openCreate() {
    setNewEmployeeId(applied.employeeId);
    setNewType(applied.itemType || '인사고과');
    setTitle('');
    setContent('');
    setStartDate('');
    setEndDate('');
    setCreating(true);
  }

  function openEdit(row: Row) {
    setTitle(String(row.title ?? ''));
    setContent(String(row.detail ?? ''));
    setStartDate(row.startDate ? String(row.startDate) : '');
    setEndDate(row.endDate ? String(row.endDate) : '');
    setDetail(null);
    setEditing(row);
  }

  function checkInput(): string {
    if (title.trim() === '') {
      return '항목명을 입력하세요.';
    }
    if (startDate !== '' && endDate !== '' && startDate > endDate) {
      return '시작일이 종료일보다 늦을 수 없습니다.';
    }
    return '';
  }

  function bodyOf(): Row {
    const body: Row = { title: title.trim() };
    if (content !== '') {
      body.detail = content;
    }
    if (startDate !== '') {
      body.startDate = startDate;
    }
    if (endDate !== '') {
      body.endDate = endDate;
    }
    return body;
  }

  async function create() {
    if (newEmployeeId === '') {
      throw new Error('임직원을 선택하세요.');
    }
    const problem = checkInput();
    if (problem) {
      throw new Error(problem);
    }
    const body = bodyOf();
    body.employeeId = newEmployeeId;
    body.itemType = newType;
    await call('POST', '/hr-card-items', role, body);
    notify('등록했습니다.');
    setCreating(false);
    list.reload();
  }

  async function update() {
    if (!editing) {
      return;
    }
    const problem = checkInput();
    if (problem) {
      throw new Error(problem);
    }
    await call('PATCH', '/hr-card-items/' + String(editing.hrCardItemId), role, bodyOf());
    notify('수정했습니다.');
    setEditing(null);
    list.reload();
  }

  return (
    <div className="bento">
      <section className="box span-12">
        <h2>조회 건수</h2>
        <Tiles items={[['고과·상벌 항목', total]]} />
      </section>
      <section className="box span-12">
        <h2>고과 및 상벌현황</h2>
        <Filters onSearch={search} onReset={reset}>
          <Field label="임직원 ID" required>
            <LookupSelect table="employee" role={role} value={employeeId} onChange={setEmployeeId} />
          </Field>
          <Field label="항목 유형">
            <Select value={itemType} onChange={setItemType} options={TYPES} />
          </Field>
        </Filters>
        <Band total={total}>
          <button type="button" onClick={openCreate}>등록</button>
        </Band>
        {list.error ? <ErrorText text={list.error} /> : null}
        <DataTable
          rows={rows}
          empty={applied.employeeId === '' ? '임직원을 선택하고 조회하세요.' : '조회 결과가 없습니다.'}
          onRowClick={(row) => setDetail(row)}
          columns={[
            { key: 'employeeId', label: '임직원 ID', render: (r) => <RefName table="employee" role={role} value={r.employeeId} /> },
            { key: 'itemType', label: '항목 유형', render: (r) => <Badge value={r.itemType} /> },
            { key: 'title', label: '항목명' },
            { key: 'startDate', label: '시작일', render: (r) => <DateText value={r.startDate} /> },
            { key: 'endDate', label: '종료일', render: (r) => <DateText value={r.endDate} /> },
            {
              key: 'edit',
              label: '처리',
              render: (r) => (
                <button
                  type="button"
                  onClick={(e) => {
                    e.stopPropagation();
                    openEdit(r);
                  }}
                >
                  수정
                </button>
              ),
            },
          ]}
        />
        <Pager page={page} size={SIZE} total={total} onPage={setPage} />
      </section>

      {detail ? (
        <Drawer title="고과·상벌 상세" onClose={() => setDetail(null)}>
          <Pairs
            items={[
              ['임직원 ID', <RefName table="employee" role={role} value={detail.employeeId} />],
              ['항목 유형', <Badge value={detail.itemType} />],
              ['항목명', String(detail.title ?? '')],
              ['상세 내용', String(detail.detail ?? '')],
              ['시작일', <DateText value={detail.startDate} />],
              ['종료일', <DateText value={detail.endDate} />],
              ['관련자명', String(detail.relatedPersonName ?? '')],
            ]}
          />
          <button type="button" onClick={() => openEdit(detail)}>수정</button>
        </Drawer>
      ) : null}

      {creating ? (
        <Drawer title="고과·상벌 등록" onClose={() => setCreating(false)}>
          <Form onSubmit={create} submit="등록">
            <Field label="임직원 ID" required>
              <LookupSelect table="employee" role={role} value={newEmployeeId} onChange={setNewEmployeeId} />
            </Field>
            <Field label="항목 유형" required>
              <Select value={newType} onChange={setNewType} options={TYPES} />
            </Field>
            <Field label="항목명" required>
              <TextInput value={title} onChange={setTitle} />
            </Field>
            <Field label="상세 내용" wide>
              <TextInput value={content} onChange={setContent} multiline />
            </Field>
            <Field label="시작일">
              <DateInput value={startDate} onChange={setStartDate} />
            </Field>
            <Field label="종료일">
              <DateInput value={endDate} onChange={setEndDate} />
            </Field>
          </Form>
        </Drawer>
      ) : null}

      {editing ? (
        <Drawer title="고과·상벌 수정" onClose={() => setEditing(null)}>
          <Form onSubmit={update} submit="수정">
            <Field label="항목명" required>
              <TextInput value={title} onChange={setTitle} />
            </Field>
            <Field label="상세 내용" wide>
              <TextInput value={content} onChange={setContent} multiline />
            </Field>
            <Field label="시작일">
              <DateInput value={startDate} onChange={setStartDate} />
            </Field>
            <Field label="종료일">
              <DateInput value={endDate} onChange={setEndDate} />
            </Field>
          </Form>
        </Drawer>
      ) : null}
    </div>
  );
}
